package com.paybridge.sslcommerz;
import static com.github.tomakehurst.wiremock.client.WireMock.*;import static org.junit.jupiter.api.Assertions.*;import com.github.tomakehurst.wiremock.junit5.WireMockExtension;import com.paybridge.core.model.*;import java.net.URI;import org.junit.jupiter.api.*;import org.junit.jupiter.api.extension.RegisterExtension;
class SslCommerzPaymentGatewayTest {@RegisterExtension static WireMockExtension wm=WireMockExtension.newInstance().options(com.github.tomakehurst.wiremock.core.WireMockConfiguration.wireMockConfig().dynamicPort()).build();@Test void creates_hosted_session(){wm.stubFor(post("/gwprocess/v4/api.php").withRequestBody(containing("tran_id=order-1")).willReturn(okJson("{\"status\":\"SUCCESS\",\"sessionkey\":\"S1\",\"GatewayPageURL\":\"https://gateway.example/S1\"}")));var g=new SslCommerzPaymentGateway(config());var p=g.createPayment(new PaymentRequest(Money.of("100","BDT"),"order-1","Book",null,new IdempotencyKey("order-1"),null,new Customer("A Person","a@example.com",new BillingAddress("1 Road","Dhaka","1200","Bangladesh"))));assertEquals(PaymentStatus.PENDING,p.status());assertEquals("https://gateway.example/S1",p.clientActionUrl());}@Test void queries_by_transaction_id(){wm.stubFor(get(urlPathEqualTo("/validator/api/merchantTransIDvalidationAPI.php")).willReturn(okJson("{\"element\":[{\"status\":\"VALID\",\"amount\":\"100\",\"currency\":\"BDT\",\"bank_tran_id\":\"B1\"}]}")));var p=new SslCommerzPaymentGateway(config()).getPayment(new PaymentReference(PaymentProvider.SSLCOMMERZ,"order-1"));assertEquals(PaymentStatus.CAPTURED,p.status());assertEquals("B1",p.providerMetadata().get("bank_transaction_id"));}private SslCommerzConfiguration config(){URI b=URI.create(wm.baseUrl());return new SslCommerzConfiguration("store","secret",b,URI.create("https://x/s"),URI.create("https://x/f"),URI.create("https://x/c"),URI.create("https://x/i"));}}
